164	// TestReserveConflictTakesPrecedenceOverInvalidParams 验证已成功编号只要改了
165	// 请求、备件、数量或到期时刻，即使新参数本身非法，也一律按编号冲突处理。
166	func TestReserveConflictTakesPrecedenceOverInvalidParams(t *testing.T) {
167		s := newStore(t)
168		if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
169			t.Fatalf("reserve: %v", err)
170		}
171	
172		cases := []struct {
173			name      string
174			requestID string
175			partID    string
176			quantity  int
177			expiry    time.Time
178		}{
179			{"empty request", "", "part1", 5, expiryOK},
180			{"unknown request", "rMissing", "part1", 5, expiryOK},
181			{"unknown part", "r1", "partMissing", 5, expiryOK},
