186		}
187		for _, tc := range cases {
188			t.Run(tc.name, func(t *testing.T) {
189				_, err := s.Reserve("c1", tc.requestID, tc.partID, tc.quantity, tc.expiry, nowOK)
190				if !errors.Is(err, ErrConflict) {
191					t.Fatalf("got %v, want ErrConflict", err)
192				}
193			})
194		}
195	
196		// 冲突不改变承诺与库存。
197		st, _ := s.PartStatus("part1", nowOK)
198		if st.ActiveOccupied != 5 || st.PhysicalRemaining != 10 {
199			t.Fatalf("conflict changed state: %+v", st)
200		}
201		// 指定已知请求的冲突各记一条；空请求与未知请求不创建请求和历史。
202		h1, _ := s.RequestHistory("r1")
203		// 1 条成功 + 未知备件/零数量/负数量/过去到期/等于到期 共 5 条冲突。
204		if len(h1) != 6 {
205			t.Fatalf("r1 history len = %d, want 6", len(h1))
206		}
207		for _, rec := range h1[1:] {
208			if rec.Success || rec.Error != HistoryErrorConflict ||
209				rec.Eligibility != nil || rec.StockBasis != nil {
210				t.Fatalf("bad conflict record: %+v", rec)
