	if len(h1) != 6 {
		t.Fatalf("r1 history len = %d, want 6", len(h1))
	}
	for _, rec := range h1[1:] {
		if rec.Success || rec.Error != HistoryErrorConflict ||
			rec.Eligibility != nil || rec.StockBasis != nil {
