	}
}

// TestReserveRetryResultIsImmutable 验证调用方修改首次返回值或重试返回值，
// 都不能改变以后取回的首次结果、当前承诺和预留历史。
func TestReserveRetryResultIsImmutable(t *testing.T) {
	s := newStore(t)
