121	func TestEvaluateExcludedAndExpiredBothListed(t *testing.T) {
122		s := newStore(t)
123		if err := s.SubmitRequest("rBad", "p1", "FAULTX"); err != nil {
124			t.Fatalf("submit: %v", err)
125		}
126		// 第 31 天：已过保，且故障代码被除外 → 两项原因。
127		e, err := s.Evaluate("rBad", t0.Add(31*day))
128		if err != nil {
129			t.Fatalf("evaluate: %v", err)
130		}
131		if e.Eligible || len(e.Reasons) != 2 {
132			t.Fatalf("expected two reasons, got %+v", e)
133		}
134		got := map[RejectionReason]bool{}
135		for _, r := range e.Reasons {
136			got[r] = true
137		}
138		if !got[ReasonWarrantyExpired] || !got[ReasonFaultExcluded] {
139			t.Fatalf("reasons = %v, want both warranty_expired and fault_code_excluded", e.Reasons)
140		}
141		if !e.Excluded {
142			t.Fatal("expected Excluded=true")
143		}
144	
145		// 仅除外（保修期内）。
146		e2, _ := s.Evaluate("rBad", nowOK)
147		if e2.Eligible || len(e2.Reasons) != 1 || e2.Reasons[0] != ReasonFaultExcluded {
148			t.Fatalf("excluded only: got %+v", e2)
149		}
150	}
