152	func TestEvaluatePurchaseInFuture(t *testing.T) {
153		s := newStore(t)
154		e, err := s.Evaluate("r1", t0.Add(-time.Second))
155		if err != nil {
156			t.Fatalf("evaluate: %v", err)
157		}
158		if e.Eligible || len(e.Reasons) != 1 || e.Reasons[0] != ReasonPurchaseInFuture {
159			t.Fatalf("future purchase: got %+v", e)
