168		if _, err := s.Evaluate("rUnknown", nowOK); !errors.Is(err, ErrNotFound) {
169			t.Fatalf("unknown product: got %v, want ErrNotFound", err)
170		}
171		if err := s.SubmitRequest("rEmpty", "p1", ""); !errors.Is(err, ErrInvalidParam) {
172			t.Fatalf("empty fault code at submit: got %v", err)
