188			t.Fatalf("part status: %v", err)
189		}
190		if st.PhysicalRemaining != 10 || st.ActiveOccupied != 4 || st.Committable != 6 {
191			t.Fatalf("stock math: phys=%d occupied=%d committable=%d", st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
192		}
