195	func TestReserveIneligibleAndUnknown(t *testing.T) {
196		s := newStore(t)
197		if err := s.SubmitRequest("rBad", "p1", "FAULTX"); err != nil {
198			t.Fatalf("submit: %v", err)
199		}
200		if _, err := s.Reserve("c1", "rBad", "part1", 1, expiryOK, nowOK); !errors.Is(err, ErrIneligible) {
201			t.Fatalf("ineligible reserve: got %v", err)
202		}
203		if _, err := s.Reserve("c2", "rMissing", "part1", 1, expiryOK, nowOK); !errors.Is(err, ErrNotFound) {
204			t.Fatalf("unknown request: got %v", err)
205		}
206		if _, err := s.Reserve("c3", "r1", "partMissing", 1, expiryOK, nowOK); !errors.Is(err, ErrNotFound) {
207			t.Fatalf("unknown part: got %v", err)
208		}
209		if _, err := s.Reserve("c4", "r1", "part1", 0, expiryOK, nowOK); !errors.Is(err, ErrInvalidParam) {
210			t.Fatalf("zero quantity: got %v", err)
211		}
212		if _, err := s.Reserve("c5", "r1", "part1", 1, nowOK, nowOK); !errors.Is(err, ErrInvalidParam) {
213			t.Fatalf("expiry equal to now: got %v", err)
214		}
215		if _, err := s.Reserve("c6", "r1", "part1", 1, nowOK.Add(-time.Second), nowOK); !errors.Is(err, ErrInvalidParam) {
216			t.Fatalf("expiry in past: got %v", err)
217		}
218		// 失败的预留不占用数量。
219		st, _ := s.PartStatus("part1", nowOK)
220		if st.ActiveOccupied != 0 || st.Committable != 10 {
