240		if d, _ := detailByID(st, "jia"); d.Status != CommitmentActive {
241			t.Fatalf("jia status = %q, want active", d.Status)
242		}
243		// 较早时刻新使用仍成功：重试没有关闭承诺。
244		if _, err := s.Use("u1", "jia", 1, before); err != nil {
245			t.Fatalf("use after non-confirming retry: %v", err)
