377	// TestCanceledStaysCanceled 验证已取消的承诺不会被确认成 expired：晚时刻、
378	// 早时刻都显示 canceled，占用始终为零，重复取消不产生数量变化。
379	func TestCanceledStaysCanceled(t *testing.T) {
380		s := expStore(t, 5)
381		noon := t0.Add(10 * day)
382		before := noon.Add(-time.Minute)
383		after := noon.Add(time.Minute)
384		if _, err := s.Reserve("jia", "r1", "part1", 5, noon, before); err != nil {
385			t.Fatalf("reserve: %v", err)
386		}
387		if _, err := s.Use("u1", "jia", 2, before); err != nil {
388			t.Fatalf("use: %v", err)
389		}
390		if _, err := s.Cancel("jia", before); err != nil {
391			t.Fatalf("cancel: %v", err)
392		}
393	
394		for _, tm := range []time.Time{after, before} {
395			st, err := s.PartStatus("part1", tm)
396			if err != nil {
397				t.Fatalf("part status: %v", err)
398			}
399			d, _ := detailByID(st, "jia")
400			if d.Status != CommitmentCanceled {
401				t.Fatalf("at %v status = %q, want canceled", tm, d.Status)
402			}
403			if st.ActiveOccupied != 0 || st.Committable != 3 || st.PhysicalRemaining != 3 {
404				t.Fatalf("at %v stock = %+v, want phys=3 occupied=0 committable=3", tm, st)
405			}
406		}
407		c, _ := s.Commitment("jia")
408		if !c.Canceled || c.Expired {
409			t.Fatalf("canceled commitment marked expired: %+v", c)
410		}
411		// 重复取消不释放更多、不改变标记。
412		if _, err := s.Cancel("jia", after); err != nil {
413			t.Fatalf("repeat cancel: %v", err)
414		}
415		c2, _ := s.Commitment("jia")
416		if !c2.Canceled || c2.Expired || c2.Used != 2 {
417			t.Fatalf("repeat cancel changed commitment: %+v", c2)
418		}
419		// 新使用（无论时刻）一律拒绝。
420		if _, err := s.Use("u2", "jia", 1, before); !errors.Is(err, ErrCommitmentClosed) {
421			t.Fatalf("use canceled at earlier time: %v", err)
422		}
423	}
