499	// TestNewReserveStockMathConfirmsEvenWhenReserveFails 验证引用有效的新预留
500	// 即使因资格不合格或库存不足而失败，其库存核算仍确认该备件到期承诺；且
501	// 库存依据记录的是确认释放后的可承诺量。
502	func TestNewReserveStockMathConfirmsEvenWhenReserveFails(t *testing.T) {
503		s := expStore(t, 5)
504		// 第三个请求命中除外代码，始终不合格。
505		if err := s.SubmitRequest("r3", "p1", "FAULTX"); err != nil {
506			t.Fatalf("submit r3: %v", err)
507		}
508		noon := t0.Add(10 * day)
509		before := noon.Add(-time.Minute)
510		after := noon.Add(time.Minute)
511		// 甲占满五件。
512		if _, err := s.Reserve("jia", "r1", "part1", 5, noon, before); err != nil {
513			t.Fatalf("reserve jia: %v", err)
514		}
515	
516		// 晚时刻为不合格请求预留：库存核算先确认甲到期（释放五件），随后资格拒绝。
517		if _, err := s.Reserve("bad1", "r3", "part1", 1, expiryOK, after); !errors.Is(err, ErrIneligible) {
518			t.Fatalf("ineligible reserve: got %v", err)
519		}
520		// 回退时刻：甲已永久释放。
521		st1, _ := s.PartStatus("part1", before)
522		if st1.ActiveOccupied != 0 || st1.Committable != 5 {
523			t.Fatalf("ineligible reserve did not confirm expiry: %+v", st1)
524		}
525	
526		// 另一仓库：合格请求但库存不足（要求超过五件），核算同样确认到期，
527		// 失败记录的库存依据反映释放后的可承诺量。
528		s2 := expStore(t, 5)
529		if _, err := s2.Reserve("jia", "r1", "part1", 5, noon, before); err != nil {
530			t.Fatalf("reserve jia: %v", err)
531		}
532		if _, err := s2.Reserve("big", "r2", "part1", 6, expiryOK.Add(2*day), after); !errors.Is(err, ErrInsufficientStock) {
533			t.Fatalf("over-stock reserve: got %v, want ErrInsufficientStock", err)
534		}
535		h, _ := s2.RequestHistory("r2")
536		if len(h) != 1 || h[0].Error != HistoryErrorInsufficientStock ||
537			h[0].StockBasis == nil || h[0].StockBasis.ActiveOccupied != 0 ||
538			h[0].StockBasis.Committable != 5 {
539			t.Fatalf("insufficient-stock record basis: %+v", h)
540		}
541		st2, _ := s2.PartStatus("part1", before)
542		if st2.ActiveOccupied != 0 || st2.Committable != 5 {
543			t.Fatalf("insufficient-stock reserve did not confirm expiry: %+v", st2)
544		}
545	}
546	
547	// TestRequestViewEligibilityUsesCurrentTimeAfterConfirmation 验证确认到期不
548	// 改变资格规则：曾用较大（过保）时刻查询确认到期，回退到保修期内查询时，
549	// 资格仍按本次较早时刻判合格，不被历史大时刻替换。
550	func TestRequestViewEligibilityUsesCurrentTimeAfterConfirmation(t *testing.T) {
551		s := expStore(t, 5)
552		noon := t0.Add(10 * day)
553		afterWarranty := t0.Add(31 * day) // 第 31 天：已过保。
554		withinWarranty := t0.Add(11 * day)
555		if _, err := s.Reserve("jia", "r1", "part1", 5, noon, t0.Add(9*day)); err != nil {
556			t.Fatalf("reserve jia: %v", err)
557		}
558		// 过保时刻查询：确认甲到期，资格不合格。
559		v1, err := s.RequestView("r1", afterWarranty)
560		if err != nil {
561			t.Fatalf("view after warranty: %v", err)
562		}
563		if v1.Eligibility.Eligible {
564			t.Fatalf("expected ineligible at day 31: %+v", v1.Eligibility)
565		}
566		// 回退到保修期内：甲保持到期，但资格按本次时刻判合格。
567		v2, err := s.RequestView("r1", withinWarranty)
568		if err != nil {
569			t.Fatalf("view within warranty: %v", err)
570		}
571		if !v2.Eligibility.Eligible || len(v2.Eligibility.Reasons) != 0 {
572			t.Fatalf("eligibility not re-judged at earlier time: %+v", v2.Eligibility)
573		}
574		if v2.Commitments[0].Status != CommitmentExpired {
575			t.Fatalf("jia status = %q, want expired", v2.Commitments[0].Status)
576		}
577	}
578	
579	// TestPartiallyUsedExpiredOnlyReleasesRemainder 验证到期只释放未用部分：
580	// 甲用掉两件后到期，实物只剩三件、可再承诺三件，无法按五件重复预留。
581	func TestPartiallyUsedExpiredOnlyReleasesRemainder(t *testing.T) {
582		s := expStore(t, 5)
583		noon := t0.Add(10 * day)
584		before := noon.Add(-time.Minute)
585		after := noon.Add(time.Minute)
586		if _, err := s.Reserve("jia", "r1", "part1", 5, noon, before); err != nil {
587			t.Fatalf("reserve jia: %v", err)
588		}
589		if _, err := s.Use("u1", "jia", 2, before); err != nil {
590			t.Fatalf("use jia: %v", err)
591		}
592		// 到期后乙只能预留剩余实物三件。
593		if _, err := s.Reserve("yi", "r2", "part1", 3, expiryOK, after); err != nil {
594			t.Fatalf("reserve yi 3: %v", err)
595		}
596		if _, err := s.Reserve("bing", "r2", "part1", 1, expiryOK.Add(time.Hour), after); !errors.Is(err, ErrInsufficientStock) {
597			t.Fatalf("reserve bing 1: got %v, want ErrInsufficientStock", err)
598		}
599		// 较早时刻回退查询：仍只有乙占用三件。
600		st, _ := s.PartStatus("part1", before)
601		if st.PhysicalRemaining != 3 || st.ActiveOccupied != 3 || st.Committable != 0 {
602			t.Fatalf("rollback stock = %+v, want phys=3 occupied=3 committable=0", st)
603		}
604	}
605

